import{_ as a,c as e,o as n,b2 as t}from"./chunks/framework.CUhoHPxN.js";const b=JSON.parse('{"title":"前端项目结构","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/structure.md","filePath":"docs/frontend/structure.md"}'),l={name:"docs/frontend/structure.md"};function i(d,s,o,r,p,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="前端项目结构" tabindex="-1">前端项目结构 <a class="header-anchor vp-link" href="#前端项目结构" aria-label="Permalink to &quot;前端项目结构&quot;">​</a></h1><h2 id="顶层目录" tabindex="-1">顶层目录 <a class="header-anchor vp-link" href="#顶层目录" aria-label="Permalink to &quot;顶层目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>quick-ui/</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>├── vite.config.js</span></span>
<span class="line"><span>├── .env.development / .env.production</span></span>
<span class="line"><span>└── src/</span></span>
<span class="line"><span>    ├── main.js              # 入口：Pinia、Router、C7、插件、指令</span></span>
<span class="line"><span>    ├── permission.js        # 路由守卫</span></span>
<span class="line"><span>    ├── settings.js          # 应用配置、白名单</span></span>
<span class="line"><span>    ├── api/                 # 接口模块</span></span>
<span class="line"><span>    ├── views/               # 页面</span></span>
<span class="line"><span>    ├── packages/            # C7 组件库</span></span>
<span class="line"><span>    ├── components/          # 通用/布局组件</span></span>
<span class="line"><span>    ├── layout/              # 主布局</span></span>
<span class="line"><span>    ├── router/index.js      # 常量路由</span></span>
<span class="line"><span>    ├── store/               # Pinia</span></span>
<span class="line"><span>    ├── utils/               # 工具</span></span>
<span class="line"><span>    ├── plugins/             # 全局插件</span></span>
<span class="line"><span>    ├── directive/           # 权限指令</span></span>
<span class="line"><span>    └── assets/              # 样式、SVG</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="路由模型" tabindex="-1">路由模型 <a class="header-anchor vp-link" href="#路由模型" aria-label="Permalink to &quot;路由模型&quot;">​</a></h2><p><strong>常量路由</strong>（<code>router/index.js</code>）：登录、404、首页、字典数据子页、代码生成编辑页等。</p><p><strong>动态路由</strong>（<code>store/modules/permission.js</code>）：</p><ol><li>用户登录成功</li><li>调用 <code>getRouters</code> 获取菜单树</li><li>将后端 <code>component</code> 字段映射为 <code>views/**/*.vue</code></li><li><code>router.addRoute</code> 挂载到 Layout 下</li></ol><p>OAuth 管理菜单通常由 Flyway（如 <code>V26__oauth2_menu.sql</code>）下发，<strong>不在</strong>常量路由硬编码。</p><h2 id="状态管理-pinia" tabindex="-1">状态管理（Pinia） <a class="header-anchor vp-link" href="#状态管理-pinia" aria-label="Permalink to &quot;状态管理（Pinia）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><code>user</code></td><td>Token、用户信息、角色</td></tr><tr><td><code>permission</code></td><td>路由、侧边栏菜单</td></tr><tr><td><code>settings</code></td><td>主题、布局、标签页</td></tr><tr><td><code>dict</code></td><td>字典缓存（若启用）</td></tr><tr><td><code>tagsView</code></td><td>多页签</td></tr></tbody></table></div><h2 id="请求链路-utils-request-js" tabindex="-1">请求链路（<code>utils/request.js</code>） <a class="header-anchor vp-link" href="#请求链路-utils-request-js" aria-label="Permalink to &quot;请求链路（\`utils/request.js\`）&quot;">​</a></h2><ol><li>从 Cookie 读取 <code>Admin-Token</code>，写入 <code>Authorization: Bearer …</code></li><li><code>applyClientSignHeaders</code>：按 canonical 算法加 <code>X-Client-*</code> 头</li><li>响应统一处理：<code>code !== 200</code> 提示、401 触发重登</li><li>下载场景单独处理 blob</li></ol><p>签名实现与后端一致：<code>utils/clientSign.js</code>。</p><h2 id="c7-组件库-packages" tabindex="-1">C7 组件库（<code>packages/</code>） <a class="header-anchor vp-link" href="#c7-组件库-packages" aria-label="Permalink to &quot;C7 组件库（\`packages/\`）&quot;">​</a></h2><p>通过 <code>packages/index.js</code> → <code>installPackages(app)</code> 全局注册。</p><div class="vp-table"><table><thead><tr><th>组件</th><th>用途</th></tr></thead><tbody><tr><td>C7JsonTable / C7JsonTableColumn</td><td>JSON 配置列表（核心）</td></tr><tr><td>C7JsonForm</td><td>JSON 配置表单</td></tr><tr><td>C7ExcelUpload / C7ExcelDownload</td><td>导入导出</td></tr><tr><td>C7DictTag</td><td>字典标签</td></tr><tr><td>C7Dialog、C7MessageBox</td><td>弹窗</td></tr><tr><td>C7DatePicker、C7TimePicker、C7TreeSelect、C7Cascader</td><td>表单控件</td></tr><tr><td>C7Button、C7Card、C7Title、C7Watermark 等</td><td>布局与展示</td></tr></tbody></table></div><p>组件文档目录：<code>docs/frontend/components/通用组件/</code>（持续补齐）。</p><h2 id="权限" tabindex="-1">权限 <a class="header-anchor vp-link" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><ul><li><strong>路由级</strong>：动态菜单 + 后端 <code>perms</code></li><li><strong>按钮级</strong>：<code>v-hasPermi=&quot;[&#39;system:user:add&#39;]&quot;</code></li><li><strong>编程式</strong>：<code>checkPermission</code>、<code>$auth.hasPermi</code></li></ul><h2 id="列表页规范" tabindex="-1">列表页规范 <a class="header-anchor vp-link" href="#列表页规范" aria-label="Permalink to &quot;列表页规范&quot;">​</a></h2><p>新建业务列表页应：</p><ol><li>优先使用 <strong>C7JsonTable</strong></li><li>布局/样式参照 <code>src/views/system/config/index.vue</code></li><li>遵循仓库 <code>DESIGN.md</code> 与 <code>sdd/前端代码规范.md</code></li></ol><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./index.html" class="vp-link">前端概述</a></li><li><a href="./modules/index.html" class="vp-link">业务页面总览</a></li></ul>`,24)])])}const h=a(l,[["render",i]]);export{b as __pageData,h as default};
